 id:'QC-01',
 title:'A buyer cannot capture a supplier quotation, and a supplier revision destroys the offer it replaces',
 capabilityIds:['SUP-02','SUP-03','SUP-04','SUP-05','SUP-06'],
 classification:'PARTIAL',
 kind:'fresh finding — capture workflow, discovered while proving SUP-06',
